-- Power Dance Lab 3.17.2: 40 individually traceable CC0 clips.

on conflict (slug) do update set
  name=excluded.name, instrument_role=excluded.instrument_role, manifest=excluded.manifest,
  license_name=excluded.license_name, license_source=excluded.license_source, bundled=excluded.bundled,
  updated_at=now();

select 'release-power-dance-cc0-library','release','Power Dance CC0 Samplebibliothek',
  '40 einzeln nachverfolgbare CC0-Samples: 30 Rhythmus/Effekt- und 10 Melodie-Kandidaten; Superadmin-Hörprobe, Aktivierung und Löschen.',
  'done','3.17.2',array['music','power-dance','superadmin','samples','cc0']
where not exists (select 1 from public.vt_project_log where entry_key='release-power-dance-cc0-library' and status <> 'superseded');
